  gateConditionalSlots: z
    .array(z.strictObject({ whenDiffMatches: z.array(nonEmpty).min(1), slot: nonEmpty }))
    .optional(),
  // Estate filter for the lint-diff hygiene slot (optional): only phase-own files matching one
